#!/usr/bin/env python3
"""Extract reached charset AND/OR semantic checkpoint from exact runtime."""
import argparse,hashlib,json,subprocess
from pathlib import Path
HERE=Path(__file__).resolve().parent;ROOT=HERE.parents[3]
def generate(out,runtime=None):
 baseline=bytes.fromhex(json.loads((ROOT/'artifacts/contracts/Operations.sol/Operations.json').read_text())['deployedBytecode'][2:]);inv=json.loads((HERE.parent/'inventory.json').read_text());assert hashlib.sha256(baseline).hexdigest()==inv['runtimeSha256'];code=runtime.read_bytes() if runtime else baseline;diff=[i for i,(a,b) in enumerate(zip(code,baseline)) if a!=b];assert len(code)==len(baseline) and baseline[4164]==22 and (not diff or diff==[4164] and code[4164]==23)
 pre=[0x3e8c97e3,1289,100,1,0,0,0,1,128,0];post=pre[:-2]+[0]
 body='// SPDX-License-Identifier: MIT\n// Generated reached AND semantic checkpoint; native pending.\ninclude "../charset-controls/Kernel.dfy"\nmodule OperationsCharsetSemanticWitness {\n  import S = BytecodeScanMachine\n  import G = BytecodeGetterMachine\n  import C = BytecodeCopyMachine\n  import M = BytecodeExternalMachine\n  import K = OperationsCharsetKernel\n  import I = OperationsCharsetInputs\n  lemma Witness(code:seq<S.Byte>,destinations:set<nat>,self:S.Word,value:S.Word,data:seq<S.Byte>,observations:seq<M.Observation>)\n    requires |code|==@SIZE@ && code[4164]==@OP@\n    ensures M.Step(code,destinations,M.Frame(S.Running(4164,@PRE@,K.Initial()),[],0),self,value,data,observations)==M.Frame(S.Running(4165,@POST@,K.Initial()),[],0)\n  {\n    assert !I.Member(0,7);\n    assert S.Fetch(code,4164)==S.Op(@OP@,4165,0);\n    reveal M.Step();reveal C.Step();reveal S.Step();reveal G.Step();\n  }\n}\n'
 body=body.replace('@SIZE@',str(len(code))).replace('@OP@',str(code[4164])).replace('@PRE@','['+','.join(map(str,pre))+']').replace('@POST@','['+','.join(map(str,post))+']');r=subprocess.run(['/tmp/assertions-dafny-4.11.0/dafny/dafny','format','--stdin','--print'],input=body.replace('include "','//FORMAT_INCLUDE "'),capture_output=True,text=True);assert r.returncode==0,r.stderr;out.mkdir(parents=True,exist_ok=True);(out/'Witness.generated.dfy').write_text(r.stdout.replace('//FORMAT_INCLUDE "','include "'));(out/'witness.mapping.json').write_text(json.dumps(dict(runtimeSha256=hashlib.sha256(code).hexdigest(),candidate=bool(diff),pc=4164,next=4165,opcode=code[4164],pre=pre,intendedPost=post,independentByte=7,independentMask=0),indent=2)+'\n')
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--output',type=Path,required=True);p.add_argument('--runtime',type=Path);a=p.parse_args();generate(a.output,a.runtime)
